/**
 * evals/ai/insights.json is generated by make-insights.mjs from the REAL engine. This pins it: the stored facts must equal what
 * buildFacts produces today for the stored inputs (so a change to the engine forces a regeneration), and every fact must have a
 * clean deterministic sentence (no "undefined", "NaN" or empty numbers), since that is the fallback the app shows.
 */
import fixtures from '../../evals/ai/insights.json';
import { buildFacts, type Fact } from '../../lib/domain/predict';
import { templateFor } from '../../supabase/functions/cg-ai-insights/insights';

type Case = { id: string; input: Parameters<typeof buildFacts>[0]; facts: Fact[]; mustCover: string[] };
const cases = (fixtures as unknown as { cases: Case[] }).cases;

describe('evals/ai/insights.json', () => {
  it('has the 10 planned cases with unique ids', () => {
    expect(cases).toHaveLength(10);
    expect(new Set(cases.map((c) => c.id)).size).toBe(10);
  });

  it.each(cases.map((c) => [c.id, c] as const))('%s: stored facts equal the engine output (run make-insights.mjs if this fails)', (_id, c) => {
    expect(JSON.parse(JSON.stringify(buildFacts(c.input)))).toEqual(c.facts);
  });

  it.each(cases.map((c) => [c.id, c] as const))('%s: mustCover is exactly the act-level facts', (_id, c) => {
    expect(c.mustCover).toEqual(c.facts.filter((f) => f.severity === 'act').map((f) => f.id));
  });

  it('every fact has a clean sentence in both languages', () => {
    for (const c of cases) {
      for (const f of c.facts) {
        for (const lang of ['es', 'en'] as const) {
          const t = templateFor(f as never, lang);
          expect(`${t.headline} ${t.why}`).not.toMatch(/undefined|NaN|null|\bnull\b|\[object/);
          expect(t.headline.length).toBeGreaterThan(5);
          expect(t.why.length).toBeGreaterThan(10);
        }
      }
    }
  });

  it('covers the planned situations', () => {
    const kinds = new Set(cases.flatMap((c) => c.facts.map((f) => f.kind)));
    for (const k of ['reminder_projection', 'fuel_anomaly']) expect(kinds.has(k as never)).toBe(true);
    expect(cases.find((c) => c.id === 'busy-car')!.facts.length).toBeGreaterThan(5);
  });
});
